-- ============================================================
-- nielcos.ai customs: full USITC HTS schedule import
-- Source: USITC HTS 2026 Rev 19 (downloaded 2026-09-28)
-- https://www.usitc.gov/harmonized_tariff_information
-- 6,857 dutiable 8-digit lines. general_rate = Column 1 General (MFN).
-- Compound/specific rates (e.g. '3.1c/kg + 2.5%%') keep numeric NULL;
-- see rate_text. Curated keyword rows from customs_v1_seed.sql keep
-- their hand-written keywords (not overwritten on conflict).
-- Run ONCE in the Supabase SQL editor (shared project).
-- ============================================================

alter table hts_schedule add column if not exists rate_text text;
alter table hts_schedule add column if not exists revision text;

on conflict (hts_no) do update set description=excluded.description, general_rate=excluded.general_rate, unit=excluded.unit, rate_text=excluded.rate_text, revision=excluded.revision;


